    paren_string = paren_string.replace(" ", "")
    stack = []
    result = []
    current_group = ""

    for char in paren_string:
        if char == "(":
            stack.append(current_group)
            current_group = ""
        elif char == ")":
            current_group = stack.pop() + "(" + current_group + ")"
        else:
            current_group += char

    result.append(current_group)

    return result

