from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove spaces from the input string
    groups = []  # Initialize a list to store separate groups

    start = 0
    count = 0
    for i, char in enumerate(paren_string):
        if char == '(':
            count += 1
            if count == 1:
                start = i
        elif char == ')':
            count -= 1
            if count == 0:
                groups.append(paren_string[start:i+1])  # Step 2 & 3: Identify separate groups of nested parentheses and divide each group into strings

    return groups  # Step 4: Return the strings in a list

